import subprocess, os, re, hashlib, pathlib, shutil, base64, zlib, json, sys
def run(cmd,cwd="/tmp",env=None):
    e={"HOME":"/home/agent","PATH":os.environ["PATH"]}
    if env:
        e.update(env)
    return subprocess.run(cmd,shell=True,cwd=cwd,capture_output=True,text=True,env=e)

# Setup simple
dirpath="/tmp/gha_test"
shutil.rmtree(dirpath, ignore_errors=True)
os.makedirs(dirpath, exist_ok=True)

def write_envrc(content):
    with open(dirpath+"/.envrc","w") as f:
        f.write(content+"\n")
    run(f"/workspace/executable allow {dirpath}", cwd=dirpath)

# Test gha delimiter for various values
for val in ["bar","baz","qux","a\nb","a",""]:
    write_envrc(f"export FOO={val!r}" if "\n" not in val else f"export FOO=$'a\\nb'")
    # For newline we use $'a\nb'
    if val=="a\nb":
        write_envrc("export FOO=$'a\\nb'")
    elif val=="":
        write_envrc("export FOO=''")
    else:
        # Use simple export with proper bash quoting? Let's just write export FOO=val where val is simple alphanumeric to avoid quoting issues
        if val.isalnum() and val:
            write_envrc(f"export FOO={val}")
        elif val=="":
            write_envrc(f"export FOO=''")
        else:
            # for newline use $''
            write_envrc(f"export FOO=$'a\\nb'")
            if val!="a\nb":
                continue
    res=run("/workspace/executable export gha", cwd=dirpath)
    # Extract delimiters
    # Format: VAR<<ghadelimiter_<hex>\nvalue\n...
    lines=res.stdout.splitlines()
    # Find FOO delimiter
    for i,line in enumerate(lines):
        if line.startswith("FOO<<"):
            delim=line.split("<<")[1]
            # hex part
            hexpart=delim.replace("ghadelimiter_","")
            print(f"val {val!r} -> FOO delimiter {delim} hex {hexpart}")
            # compute md5 of value
            md5_val=hashlib.md5(val.encode()).hexdigest()
            print(f"  md5(val) {md5_val}")
            # md5 of "FOO=val"
            md5_kv=hashlib.md5(f"FOO={val}".encode()).hexdigest()
            print(f"  md5(FOO=val) {md5_kv}")
            # md5 of val with newline? etc.
            # Try sha256 first 32
            sha256_val=hashlib.sha256(val.encode()).hexdigest()[:32]
            print(f"  sha256(val)[:32] {sha256_val}")
            # Try to see if delimiter is md5 of something like value + key?
            # Let's also compute what string would produce this md5: we have delimiter hex, we can try to reverse? No.
            # Could be that delimiter is md5 of value itself but with some salt like "direnv" ?
            for salt in ["", "direnv", "gha"]:
                print(f"  md5(salt+val) salt={salt!r} {hashlib.md5((salt+val).encode()).hexdigest()} vs target {hexpart} match? {hashlib.md5((salt+val).encode()).hexdigest()==hexpart}")
            break
    print("---")

# Test systemd
for val in ["bar","a b","a\nb","a\"b","a'b","a=b",""]:
    if val=="a\nb":
        write_envrc("export FOO=$'a\\nb'")
    elif val=="":
        write_envrc("export FOO=''")
    elif val=="a b":
        write_envrc("export FOO='a b'")
    elif val=='a"b':
        write_envrc(r"export FOO='a\"b'")
    elif val=="a'b":
        write_envrc(r"export FOO=$'a\'b'")
    elif val=="a=b":
        write_envrc("export FOO='a=b'")
    else:
        write_envrc(f"export FOO={val}")

    res=run("/workspace/executable export systemd", cwd=dirpath)
    print(f"systemd val {val!r} -> stdout {res.stdout!r}")

