	var watches []Watch
	if err := json.Unmarshal(dec, &watches); err != nil {
		return nil, err
	}
	return watches, nil
}

func decodeDiff(s string) (*EnvDiff, error) {
	if s == "" {
		return &EnvDiff{Prev: map[string]string{}, Next: map[string]string{}}, nil
	}
	pad := len(s) % 4
	if pad != 0 {
		s += strings.Repeat("=", 4-pad)
	}
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		return nil, err
	}
	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	dec, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	var d EnvDiff
	if err := json.Unmarshal(dec, &d); err != nil {
		return nil, err
	}
	if d.Prev == nil {
		d.Prev = map[string]string{}
	}
	if d.Next == nil {
		d.Next = map[string]string{}
	}
	return &d, nil
}

func encodeDiff(d *EnvDiff) string {
	b, _ := json.Marshal(d)
	var buf bytes.Buffer
	w := zlib.NewWriter(&buf)
	w.Write(b)
	w.Close()
	enc := base64.URLEncoding.EncodeToString(buf.Bytes())
	enc = strings.TrimRight(enc, "=")
	return enc
}

func getEnvMap() map[string]string {
	env := map[string]string{}
	for _, kv := range os.Environ() {
		parts := strings.SplitN(kv, "=", 2)
		if len(parts) == 2 {
			env[parts[0]] = parts[1]
		} else {
			env[parts[0]] = ""
		}
	}
	return env
}

func findRC(startDir string, loadDotenv bool) (string, string) {
	// Walk up from startDir looking for .envrc and .env
	// Returns rcPath and type? Actually need to find first .envrc or .env found in current and parent directories.
	// Precedence: .envrc chosen first if both exist? In earlier test with both .envrc and .env, and load_dotenv true, .envrc was chosen.
	// So logic: At each directory level, check for .envrc existence, if exists, return it (if allowed? But findRC just finds path, not check allowed)
	// If not .envrc, and loadDotenv true, check .env

	dir := startDir
	for {
		// Check .envrc
		rc1 := filepath.Join(dir, ".envrc")
		if fi, err := os.Stat(rc1); err == nil && !fi.IsDir() {
			return rc1, "envrc"
		}
		if loadDotenv {
			rc2 := filepath.Join(dir, ".env")
			if fi, err := os.Stat(rc2); err == nil && !fi.IsDir() {
				return rc2, "env"
			}
		}
		// parent
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", ""
}

func isAllowed(rcPath string, cfg *Config) (int, string, string) {
	// Check whitelist first
	// Expand whitelist prefix and exact maps already have absolute paths
	// For prefix: if rcPath has prefix of any whitelist prefix, allowed = 0 ?
	// For exact: if rcPath equals exact entry, allowed.

	// Resolve rcPath to absolute
	absPath, err := filepath.Abs(rcPath)
	if err != nil {
		absPath = rcPath
	}
	absPath, _ = filepath.EvalSymlinks(absPath)
	if absPath == "" {
		absPath = rcPath
	}
	// Check exact
	if cfg.WhitelistExact[absPath] {
		return 0, "", ""
	}
	// Check prefix
	for _, pref := range cfg.WhitelistPrefix {
