		}
	}

	dataDir := getDataDir()
	allowDir := filepath.Join(dataDir, "allow")
	denyDir := filepath.Join(dataDir, "deny")

	// Deny hash = sha256(path + "\n")
	hDeny := sha256.Sum256([]byte(absPath + "\n"))
	denyHash := hex.EncodeToString(hDeny[:])
	denyPath := filepath.Join(denyDir, denyHash)

	// If deny file exists, blocked with reason 2?
	if _, err := os.Stat(denyPath); err == nil {
		return 2, denyPath, ""
	}

	// Allow: need to check if any allow file for this path with matching content exists
	// Allow files contain path + "\n" as content, and filename = sha256(path+"\n"+contentOfRC)
	// Read RC content
	rcContent, err := os.ReadFile(absPath)
	if err != nil {
		// Can't read? Then blocked? Return 1?
		return 1, "", denyPath
	}
	hAllow := sha256.Sum256([]byte(absPath + "\n" + string(rcContent)))
	allowHash := hex.EncodeToString(hAllow[:])
	allowPath := filepath.Join(allowDir, allowHash)

	if _, err := os.Stat(allowPath); err == nil {
		return 0, allowPath, denyPath
	}
	// Also check if there is any allow file that contains same path but with old content? Actually for isAllowed we should check if any allow file for this path exists that matches current content. If not, blocked = 1, allowPath is expected path for current content (for status display)
	// For status, we need to show allowPath as expected allow file path for current RC (hash of path+nl+content)

	// So return blocked, with allowPath being expected path, denyPath being deny hash path
	return 1, allowPath, denyPath
}

func computeWatches(rcPath string, rcModTime int64, allowPath string, allowMod, denyPath string, extraWatches []Watch) []Watch {
	// watches always include RC file, allow file, deny file
	var watches []Watch
	// RC file
	mod := rcModTime
	if mod == 0 {
		// stat
		if fi, err := os.Stat(rcPath); err == nil {
			mod = fi.ModTime().Unix()
		}
	}
	watches = append(watches, Watch{Path: rcPath, Modtime: mod, Exists: true})

	// allow file
	var allowExists bool
	var allowModTime int64
	if allowPath != "" {
		if fi, err := os.Stat(allowPath); err == nil {
			allowExists = true
			allowModTime = fi.ModTime().Unix()
		} else {
			allowExists = false
			allowModTime = 0
		}
		watches = append(watches, Watch{Path: allowPath, Modtime: allowModTime, Exists: allowExists})
	}

	// deny file
	var denyExists bool
	var denyModTime int64
	if denyPath != "" {
		if fi, err := os.Stat(denyPath); err == nil {
			denyExists = true
			denyModTime = fi.ModTime().Unix()
		} else {
			denyExists = false
			denyModTime = 0
		}
		watches = append(watches, Watch{Path: denyPath, Modtime: denyModTime, Exists: denyExists})
	}

	// extra watches from stdlib watch_file and watch_dir
	// extraWatches already includes path, modtime, exists for each
	// But need to avoid duplicates? Keep as is
	watches = append(watches, extraWatches...)

	return watches
}

func bashEscapeValue(v string) string {
	// For bash $'' quoting
	// Always use $'' except empty => ''
	if v == "" {
		return "''"
	}
	// Escape: backslash -> \\, single quote -> \', newline -> \n, \r -> \r, \t -> \t, etc.
	// Also need to escape $'? What about other special chars? In $'' quoting, \ is escape, ' ends quoting? But we escape ' as \'
	// We'll escape: \ -> \\, ' -> \', \a \b \e \f \n \r \t \v
	var sb strings.Builder
	sb.WriteString("$'")
	for _, r := range v {
		switch r {
		case '\\':
			sb.WriteString("\\\\")
		case '\'':
			sb.WriteString("\\'")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\a':
			sb.WriteString("\\a")
		case '\b':
			sb.WriteString("\\b")
		case '\v':
			sb.WriteString("\\v")
		case '\f':
			sb.WriteString("\\f")
		case '\x1b':
			sb.WriteString("\\e")
		default:
			if r < 32 || r == 127 {
				// hex?
				sb.WriteString(fmt.Sprintf("\\x%02x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

