func exportBashLike(diffPrev *EnvDiff, newDiff *EnvDiff, currentEnv map[string]string) string {
	// Compute transformation from currentEnv (which has old diff applied) to new env (clean baseline + newDiff)
	// Steps:
	// oldDiff = diffPrev (decoded from DIRENV_DIFF)
	// cleanEnv = revert oldDiff from currentEnv
	// newEnv = cleanEnv + newDiff.Next
	// To get transformation from currentEnv to newEnv, we need to compute which keys to set/unset.

	// currentEnv is map of current env vars (including DIRENV_*)
	// cleanEnv = currentEnv with oldDiff reverted: for each k,v in oldDiff.Next, if k in oldDiff.Prev, set to Prev, else delete

	clean := make(map[string]string)
	for k, v := range currentEnv {
		clean[k] = v
	}
	if diffPrev != nil {
		for k := range diffPrev.Next {
			if pv, ok := diffPrev.Prev[k]; ok {
				clean[k] = pv
			} else {
				delete(clean, k)
			}
		}
	}

	// newEnv = clean + newDiff.Next
	newEnv := make(map[string]string)
	for k, v := range clean {
		newEnv[k] = v
	}
	for k, v := range newDiff.Next {
		newEnv[k] = v
	}
	// Also old prev? Actually newDiff.Prev is old values for keys that were overridden? But newEnv already has clean values plus new. However newDiff.Prev is for revert purposes next time, not for newEnv.
	// For building newEnv, we already have clean (which is baseline) and we apply Next.

	// Now transformation: keys that are in currentEnv but not in newEnv => unset
	// Keys that are in newEnv and differ from currentEnv => export

	// But also we need to handle keys that were in clean but overridden? Actually currentEnv already has newDiff? Wait for export case with no diff, clean = current without old diff, newEnv = clean + newDiff.Next. For same RC, newDiff.Next = oldDiff.Next, so newEnv = currentEnv, so no diff.

	var parts []string
	// Unset first?
	for k := range currentEnv {
		if _, ok := newEnv[k]; !ok {
			// unset
			parts = append(parts, fmt.Sprintf("unset %s;", k))
		}
	}
	// Export
	// For deterministic order, sort keys that changed
	var exportKeys []string
	for k, nv := range newEnv {
		if cv, ok := currentEnv[k]; !ok || cv != nv {
			exportKeys = append(exportKeys, k)
		}
	}
	sort.Strings(exportKeys)
	for _, k := range exportKeys {
		v := newEnv[k]
		parts = append(parts, fmt.Sprintf("export %s=%s;", k, bashEscapeValue(v)))
	}
	return strings.Join(parts, "")
}

