func formatSystemdLine(k, v string) string {
	if v == "" {
		return fmt.Sprintf("%s=", k)
	}
	needsQuote := strings.Contains(v, "\n") || strings.Contains(v, "\"") || strings.Contains(v, "'")
	// Also if contains backslash?
	if strings.Contains(v, "\\") {
		needsQuote = true
	}
	if !needsQuote {
		return fmt.Sprintf("%s=%s", k, v)
	}
	// Escape backslash first, then double quote
	esc := strings.ReplaceAll(v, "\\", "\\\\")
	esc = strings.ReplaceAll(esc, "\"", "\\\"")
	// Note: single quote may need escaping? In example "a'b" gave "a\'b" inside double quotes, so escape single quote as \' ?
	// Let's escape single quote as \'
	// But inside double quotes in systemd, single quote doesn't need escaping, but observed shows it was escaped.
	esc = strings.ReplaceAll(esc, "'", "\\'")
	// Now wrap in double quotes
	return fmt.Sprintf("%s=\"%s\"", k, esc)
}

