func parseTomlString(val string) (string, error) {
	val = strings.TrimSpace(val)
	if len(val) >= 2 && ((val[0] == '"' && val[len(val)-1] == '"') || (val[0] == '\'' && val[len(val)-1] == '\'')) {
		// Use strconv.Unquote for double quoted, but handle single quoted as raw
		if val[0] == '"' {
			if u, err := strconv.Unquote(val); err == nil {
				return u, nil
			}
			return val[1 : len(val)-1], nil
		} else {
			// single quoted literal: no escape processing (but '' is not)
			// For simplicity, trim
			if strings.HasPrefix(val, "'''") && strings.HasSuffix(val, "'''") {
				return val[3 : len(val)-3], nil
			}
			return val[1 : len(val)-1], nil
		}
	}
	return val, nil
}

func parseBool(val string) (bool, bool) {
	val = strings.TrimSpace(strings.ToLower(val))
	if val == "true" {
		return true, true
	}
	if val == "false" {
		return false, true
	}
	return false, false
}

func parseStringArraySimple(val string) []string {
	// expects format [ "a", "b" ] possibly with spaces
	val = strings.TrimSpace(val)
	if !strings.HasPrefix(val, "[") {
		return nil
	}
	// find closing ]
	end := strings.LastIndex(val, "]")
	if end == -1 {
		return nil
	}
	inner := val[1:end]
	inner = strings.TrimSpace(inner)
	if inner == "" {
		return []string{}
	}
	var res []string
	// naive split respecting quotes
	var cur strings.Builder
	inDouble := false
	inSingle := false
	escape := false
	for _, r := range inner {
		if escape {
			cur.WriteRune(r)
			escape = false
			continue
		}
		if r == '\\' {
			// keep? We'll treat as escape for next
			escape = true
			continue
		}
		if r == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if r == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if r == ',' && !inDouble && !inSingle {
			s := strings.TrimSpace(cur.String())
			s = strings.Trim(s, "\"'")
			s = expandUser(s)
			if s != "" {
				res = append(res, s)
			}
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if cur.Len() > 0 {
		s := strings.TrimSpace(cur.String())
		s = strings.Trim(s, "\"'")
		s = expandUser(s)
		if s != "" {
			res = append(res, s)
		}
	}
	return res
}

