func genGhaDelim() string {
	b := make([]byte, 16)
	rand.Read(b)
	return "ghadelimiter_" + hex.EncodeToString(b)
}

func escapeTcshVal(v string) string {
	if v == "" {
		return "''"
	}
	var sb strings.Builder
	for _, r := range v {
		switch r {
		case ' ':
			sb.WriteString("\\ ")
		case '\'':
			sb.WriteString("\\'")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteRune('\n')
		case '\r':
			sb.WriteRune('\r')
		case '\t':
			sb.WriteRune('\t')
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func formatSystemd(k, v string) string {
	if v == "" {
		return fmt.Sprintf("%s=", k)
	}
	needsQuote := strings.Contains(v, "\n") || strings.Contains(v, "\"") || strings.Contains(v, "'")
	if strings.Contains(v, "\\") {
		needsQuote = true
	}
	if !needsQuote {
		return fmt.Sprintf("%s=%s", k, v)
	}
	esc := strings.ReplaceAll(v, "\\", "\\\\")
	esc = strings.ReplaceAll(esc, "\"", "\\\"")
	esc = strings.ReplaceAll(esc, "'", "\\'")
	return fmt.Sprintf("%s=\"%s\"", k, esc)
}

// Dotenv parsing

func parseDotenvBytes(data []byte) (map[string]string, error) {
	// Implement parser as per observed behavior
	// Handle multi-line quoted values
	env := make(map[string]string)
	content := string(data)

	// Normalize line endings and handle multiline
	var logicalLines []string
	var cur strings.Builder
	inDouble := false
	inSingle := false
	escape := false

	for i := 0; i < len(content); i++ {
		ch := content[i]
		if escape {
			cur.WriteByte(ch)
			escape = false
			continue
		}
		if ch == '\\' && inDouble {
			cur.WriteByte(ch)
			escape = true
			continue
		}
		if ch == '"' && !inSingle {
			inDouble = !inDouble
			cur.WriteByte(ch)
			continue
		}
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
			cur.WriteByte(ch)
			continue
		}
		if ch == '\n' {
			if inDouble || inSingle {
				cur.WriteByte(ch)
				continue
			} else {
				logicalLines = append(logicalLines, cur.String())
				cur.Reset()
				continue
			}
		}
		if ch == '\r' {
			if inDouble || inSingle {
				cur.WriteByte('\n')
				if i+1 < len(content) && content[i+1] == '\n' {
					i++
				}
				continue
			} else {
				logicalLines = append(logicalLines, cur.String())
				cur.Reset()
				if i+1 < len(content) && content[i+1] == '\n' {
					i++
				}
				continue
			}
		}
		cur.WriteByte(ch)
	}
	if cur.Len() > 0 {
		logicalLines = append(logicalLines, cur.String())
	}

	for _, line := range logicalLines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		noExport := trimmed
		if strings.HasPrefix(trimmed, "export ") {
			noExport = strings.TrimSpace(trimmed[len("export "):])
		}
		eqIdx := strings.Index(noExport, "=")
		if eqIdx == -1 {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		key := strings.TrimSpace(noExport[:eqIdx])
		valPart := strings.TrimSpace(noExport[eqIdx+1:])

		if key == "" {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		matched, _ := regexp.MatchString(`^[A-Za-z0-9_\.]+$`, key)
		if !matched {
			return nil, fmt.Errorf("invalid line: %s", line)
		}

		// Parse value
		// If empty, value = ""
		if valPart == "" {
			env[key] = ""
			continue
		}
		// If starts with single quote
		if strings.HasPrefix(valPart, "'") {
			// Find closing single quote not escaped? In single quotes, \' not special except maybe? But for dotenv single quoted, backslash is literal.
			// We need to find closing '
			// However value may contain escaped? For our purposes, find last '?
			// Simpler: if valPart starts with ' and ends with ' (or contains ' with content), parse.

			// Check if single-quoted value
			if len(valPart) >= 2 && valPart[0] == '\'' {
				// Find closing '
				endIdx := -1
				for j := 1; j < len(valPart); j++ {
					if valPart[j] == '\'' {
						// In single quotes, ''? Actually no escape, so this is closing
						endIdx = j
						break
					}
				}
				if endIdx == -1 {
					return nil, fmt.Errorf("unclosed quoted value in .env file")
				}
				inner := valPart[1:endIdx]
				rest := strings.TrimSpace(valPart[endIdx+1:])
				if rest != "" {
					// If rest starts with #, it's comment, else if rest has non-space, handle accordingly
					if !strings.HasPrefix(rest, "#") {
						// Check if inner originally had spaces? For 'bar"extra' case: valuePart = "'bar'extra"? Actually for single quotes case, but we are handling single. For double case similar logic for extra.

						// For our parsing, if rest is not empty and not comment, then treat whole valuePart as unquoted literal that includes quotes (as observed for "bar"extra)
						// So this quoted parse is invalid, fallback to unquoted handling.

						// We will determine if rest after quoted value is comment or empty => valid quoted
						// Else, treat as unquoted literal (including quotes)
					}
				}
				// If valid quoted (rest empty or comment)
				if rest == "" || strings.HasPrefix(rest, "#") {
					// Single-quoted: no escape processing, literal inner
					env[key] = inner
					continue
				}
				// fallback to unquoted handling below
			}
		}
		if strings.HasPrefix(valPart, "\"") {
			if len(valPart) >= 2 && valPart[0] == '"' {
				// Need to find closing double quote that is not escaped by backslash (but backslash escapes handled)
				endIdx := -1
				esc := false
				for j := 1; j < len(valPart); j++ {
					ch := valPart[j]
					if esc {
						esc = false
						continue
					}
					if ch == '\\' {
						esc = true
						continue
					}
					if ch == '"' {
						endIdx = j
						break
					}
				}
				if endIdx == -1 {
					return nil, fmt.Errorf("unclosed quoted value in .env file")
				}
				inner := valPart[1:endIdx]
				rest := strings.TrimSpace(valPart[endIdx+1:])
				if rest != "" && !strings.HasPrefix(rest, "#") {
					// fallback to unquoted literal
				} else {
					// Process escapes and variable expansion inside double quotes
					processed := processDoubleQuoted(inner)
					// Now variable expansion
					expanded := expandDotenvVars(processed)
					env[key] = expanded
					continue
				}
			}
		}
		// Unquoted handling
		// Split at # for comment (first #)
		// But need to handle # inside? For unquoted, # always starts comment? From observed, "val#notcomment" gave "val" (comment). So # starts comment even without space.

		// So find first #
		hashIdx := strings.Index(valPart, "#")
		var valNoComment string
		if hashIdx != -1 {
			valNoComment = strings.TrimSpace(valPart[:hashIdx])
		} else {
			valNoComment = strings.TrimSpace(valPart)
		}
		// If valNoComment contains whitespace, invalid
		if strings.Contains(valNoComment, " ") || strings.Contains(valNoComment, "\t") {
			// Check if it contains quotes that would make it valid as literal with quotes? For "bar"extra case, valNoComment = "\"bar\"extra" contains no space, so valid.
			// For "bar extra" contains space, invalid.
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		// Now variable expansion for unquoted
		expanded := expandDotenvVars(valNoComment)
		// Also need to unescape? For unquoted, what about escapes? We saw unquoted with backslashes kept as is (e.g., a\nb stayed as literal backslash-n)
		env[key] = expanded
	}

	return env, nil
}

func processDoubleQuoted(s string) string {
	// Handle escapes inside double-quoted dotenv
	// Observed:
	// \n => newline
	// \r => carriage return
	// \" => "
	// \\ => \
	// \t => t (not tab)
	// \v => v, \f => f, etc remove backslash?
	// \$ => \ ? Actually we saw \$ gave backslash? Let's re-evaluate with more tests: We need to handle \$ as escaping $ to prevent expansion, but also keep $?
	// In our earlier tests with B=fromenv:
	// FOO="a\$B" gave value containing backslash? Actually with B=fromenv, "a\$B" should be a\$B -> if \$ escapes $, it should be a$B literal, but we got a\ (backslash) ?

	// Let's check again: run dotenv for "a\$B" with B=fromenv and no expansion? We did and got "a\"? Wait we saw for "a\$B" gave "a\\" (a + backslash) ?

	// Could be that processing is: \ + $ => $ (escaped), but then $B expansion would be fromenv? So "a\$B" would be "a" + "$" + "fromenv"? That would be "a$fromenv"? But we got "a\".

	// Let's handle \ escapes generally: If \ followed by n => newline, \r => \r, \" => ", \\ => \, \$ => $, and for any other char, remove backslash and keep char (so \t => t)

	// Also need to handle actual newline characters inside double quotes (multiline) already preserved.

	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == '\\' && i+1 < len(s) {
			next := s[i+1]
			switch next {
			case 'n':
				sb.WriteByte('\n')
				i++
			case 'r':
				sb.WriteByte('\r')
				i++
			case '"':
				sb.WriteByte('"')
				i++
			case '\\':
				sb.WriteByte('\\')
				i++
			case '$':
				sb.WriteByte('$')
				i++
			default:
				// For other escapes like \t, remove backslash, keep char
				sb.WriteByte(next)
				i++
			}
		} else {
			sb.WriteByte(ch)
		}
	}
	return sb.String()
}

func expandDotenvVars(s string) string {
	// Expand $VAR and ${VAR} using current env (os env)
	// For ${VAR}, VAR can be any? And for $VAR, VAR is [A-Za-z0-9_]+
	// If VAR not set, replace with empty?
	// Observed: FOO="a$B" with B=fromenv gave "afromenv", so $B expanded.
	// FOO="a$Bbar" where B=fromenv and Bbar not set gave "a" (empty for Bbar), so it tries longest? Actually $Bbar would be var Bbar, not B+bar. Since Bbar not set, empty. So it matches longest alphanumeric.

	// For ${B}bar, it expands B then bar literal -> fromenvbar (observed)

	var sb strings.Builder
	for i := 0; i < len(s); {
		if s[i] == '$' {
			if i+1 < len(s) && s[i+1] == '{' {
				// ${VAR}
				end := strings.Index(s[i:], "}")
				if end == -1 {
					// no closing } -> keep as is?
					sb.WriteByte(s[i])
					i++
					continue
				}
				varName := s[i+2 : i+end]
				val := os.Getenv(varName)
				sb.WriteString(val)
				i += end + 1
				continue
			} else {
				// $VAR
				j := i + 1
				for j < len(s) && (isAlphaNum(s[j]) || s[j] == '_') {
					j++
				}
				if j == i+1 {
					// just $, keep?
					sb.WriteByte(s[i])
					i++
					continue
				}
				varName := s[i+1 : j]
				val := os.Getenv(varName)
				sb.WriteString(val)
				i = j
				continue
			}
		} else {
			sb.WriteByte(s[i])
			i++
		}
	}
	return sb.String()
}

func isAlphaNum(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') || (b >= '0' && b <= '9')
}

func getRCInfo(startDir string, cfg *Config) (rcPath string, allowed int, allowPath, denyPath string, watches []Watch, errMsg string) {
	pwd := startDir
	rc, ok := findRCFromDir(pwd, cfg.LoadDotenv)
	if !ok {
		return "", 0, "", "", nil, ""
	}
	allowed, allowPath, denyPath = isAllowed(rc, cfg)
	// compute watches for this RC (for status, we need watches of RC, allow, deny)
	var mod int64
	if fi, err := os.Stat(rc); err == nil {
		mod = fi.ModTime().Unix()
	}
	watches = []Watch{
		{Path: rc, Modtime: mod, Exists: true},
	}
	if allowPath != "" {
		watches = append(watches, Watch{Path: allowPath, Modtime: statModTime(allowPath), Exists: fileExists(allowPath)})
	}
	if denyPath != "" {
		watches = append(watches, Watch{Path: denyPath, Modtime: statModTime(denyPath), Exists: fileExists(denyPath)})
	}
	return rc, allowed, allowPath, denyPath, watches, ""
}

