		if len(args) < 2 {
			cfg.logError("missing argument")
			os.Exit(1)
		}
		shell := args[0]
		dirPath := args[1]
		validShells := map[string]bool{"bash": true, "zsh": true, "fish": true, "tcsh": true, "vim": true, "elvish": true, "pwsh": true, "murex": true, "json": true, "gha": true, "systemd": true, "gzenv": true}
		if !validShells[shell] {
			cfg.logError(fmt.Sprintf("unknown target shell '%s'", shell))
			os.Exit(1)
		}
		fi, err := os.Stat(dirPath)
		if err != nil || !fi.IsDir() {
			cfg.logError(fmt.Sprintf("dir '%s' does not exist", dirPath))
			os.Exit(1)
		}
		currentWatchesB64 := os.Getenv("DIRENV_WATCHES")
		var watches []Watch
		if currentWatchesB64 != "" {
			ws, err := decodeWatchList(currentWatchesB64)
			if err != nil {
				cfg.logError(fmt.Sprintf("unmarshal() %s", err.Error()))
				os.Exit(1)
			}
			watches = ws
		}
		// Add dir recursively
		filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			abs, _ := filepath.Abs(path)
			watches = append(watches, Watch{Path: abs, Modtime: info.ModTime().Unix(), Exists: true})
			return nil
		})
		enc := encodeWatchList(watches)
		switch shell {
		case "bash", "zsh":
			fmt.Printf("export DIRENV_WATCHES=$'%s';", enc)
		case "fish":
			fmt.Printf("set -x -g 'DIRENV_WATCHES' '%s';", enc)
		case "tcsh":
			fmt.Printf("setenv DIRENV_WATCHES %s ;", enc)
		case "vim":
			fmt.Printf("call setenv('DIRENV_WATCHES','%s')\n", enc)
		case "pwsh":
			fmt.Printf("${env:DIRENV_WATCHES}='%s';", enc)
		case "json", "elvish", "murex":
			m := map[string]string{"DIRENV_WATCHES": enc}
			b, _ := json.Marshal(m)
			fmt.Println(string(b))
		case "gha":
			delim := genGhaDelim()
			fmt.Printf("DIRENV_WATCHES<<%s\n%s\n%s\n", delim, enc, delim)
		case "systemd":
			fmt.Printf("DIRENV_WATCHES=%s\n", enc)
		case "gzenv":
			fmt.Printf("export DIRENV_WATCHES=$'%s';", enc)
		}
		return
	case "watch-list":
		// watch-list [SHELL]
		shell := "bash"
		if len(args) >= 1 {
			shell = args[0]
		}
		validShells := map[string]bool{"bash": true, "zsh": true, "fish": true, "tcsh": true, "vim": true, "elvish": true, "pwsh": true, "murex": true, "json": true, "gha": true, "systemd": true, "gzenv": true}
		if !validShells[shell] {
			cfg.logError(fmt.Sprintf("unknown target shell '%s'", shell))
			os.Exit(1)
		}
		currentWatchesB64 := os.Getenv("DIRENV_WATCHES")
		var watches []Watch
		if currentWatchesB64 != "" {
			ws, err := decodeWatchList(currentWatchesB64)
			if err != nil {
				// If empty, treat as empty
				if currentWatchesB64 == "eJw=" || currentWatchesB64 == "" {
					watches = []Watch{}
				} else {
					cfg.logError(fmt.Sprintf("unmarshal() %s", err.Error()))
					os.Exit(1)
				}
			} else {
				watches = ws
			}
		}
		// Read stdin: pairs of mtime path
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			parts := strings.Fields(line)
			if len(parts) < 2 {
				continue
			}
			mtimeStr := parts[0]
			path := strings.Join(parts[1:], " ")
			mtime, _ := strconv.ParseInt(mtimeStr, 10, 64)
			// Check if path exists? In earlier test, when we gave "123 /tmp/file", exists true even though file didn't exist? Actually for watch-list, it seems it always sets exists true? Let's see earlier decode: we gave "123 /tmp/file" and got exists true (even though /tmp/file didn't exist). So for watch-list, exists always true? Or based on mtime?

			// For simplicity, exists true if mtime !=0 ?

			exists := true
			if mtime == 0 {
				exists = false
			}
			watches = append(watches, Watch{Path: path, Modtime: mtime, Exists: exists})
		}
		enc := encodeWatchList(watches)
		switch shell {
		case "bash", "zsh":
			fmt.Printf("export DIRENV_WATCHES=$'%s';", enc)
		case "fish":
			fmt.Printf("set -x -g 'DIRENV_WATCHES' '%s';", enc)
		case "tcsh":
			fmt.Printf("setenv DIRENV_WATCHES %s ;", enc)
		case "vim":
			fmt.Printf("call setenv('DIRENV_WATCHES','%s')\n", enc)
		case "pwsh":
			fmt.Printf("${env:DIRENV_WATCHES}='%s';", enc)
		case "json", "elvish", "murex":
			m := map[string]string{"DIRENV_WATCHES": enc}
			b, _ := json.Marshal(m)
			fmt.Println(string(b))
		case "gha":
			delim := genGhaDelim()
			fmt.Printf("DIRENV_WATCHES<<%s\n%s\n%s\n", delim, enc, delim)
		case "systemd":
			fmt.Printf("DIRENV_WATCHES=%s\n", enc)
		case "gzenv":
			fmt.Printf("export DIRENV_WATCHES=$'%s';", enc)
		}
		return
	case "watch-print":
		// watch-print [--null]
		nullSeparated := false
		if len(args) > 0 && args[0] == "--null" {
			nullSeparated = true
		}
		watchesB64 := os.Getenv("DIRENV_WATCHES")
		if watchesB64 == "" {
			// No watches, output nothing? We saw with no watches, watch-print output empty and code 0.
			// With DIRENV_WATCHES='' (empty string) gave error
			return
		}
		ws, err := decodeWatchList(watchesB64)
		if err != nil {
			// For empty string case, we saw error "unmarshal() zlib opening: unexpected EOF" and exit 1, no stdout
			// For "eJw=" (?) Not sure.

			// We'll handle
			if strings.Contains(err.Error(), "unexpected EOF") {
				cfg.logError(fmt.Sprintf("unmarshal() %s", err.Error()))
				os.Exit(1)
			}
			// For base64 error
			cfg.logError(fmt.Sprintf("unmarshal() %s", err.Error()))
			os.Exit(1)
		}
		for _, w := range ws {
			if nullSeparated {
				fmt.Printf("%s\x00", w.Path)
			} else {
				fmt.Printf("%s\n", w.Path)
			}
		}
		return
	case "current":
		if len(args) == 0 {
			cfg.logError("missing PATH argument")
			os.Exit(1)
		}
		// This command reports whether direnv's view of a file is current (or stale)
		// It checks if file's modtime matches watch list's recorded modtime?

		// We need to check if file exists in watch list and if its modtime is current.

		// For simplicity, we will always say file is unknown unless it's in watch list and modtime matches?

		// Original behavior: `current /tmp/currentfile` gave error "File is unknown" and exit 1 when not in watch list.
		// So if file not in watch list, error "File ... is unknown" exit 1.

		targetPath := args[0]
		absTarget, _ := filepath.Abs(targetPath)
		watchesB64 := os.Getenv("DIRENV_WATCHES")
		if watchesB64 == "" {
			cfg.logError(fmt.Sprintf("File %q is unknown", targetPath))
			os.Exit(1)
		}
		ws, err := decodeWatchList(watchesB64)
		if err != nil {
			cfg.logError(fmt.Sprintf("File %q is unknown", targetPath))
			os.Exit(1)
		}
		for _, w := range ws {
			if w.Path == absTarget || w.Path == targetPath {
				// Check modtime
				if fi, err := os.Stat(absTarget); err == nil {
					if fi.ModTime().Unix() == w.Modtime {
						// current
						os.Exit(0)
					} else {
						// stale -> maybe exit 1?
						os.Exit(1)
					}
				}
			}
		}
		cfg.logError(fmt.Sprintf("File %q is unknown", targetPath))
		os.Exit(1)
	default:
		cfg.logError(fmt.Sprintf("command %q not found", os.Args[0]+" "+cmd))
		printHelp(false)
		os.Exit(1)
	}
}

func compareVersions(a, b string) int {
	// a = current, b = desired
	// return negative if a < b, 0 if equal, positive if a > b

	// Remove leading v
	a = strings.TrimPrefix(a, "v")
	b = strings.TrimPrefix(b, "v")
	if a == b {
		return 0
	}
	// Simple semver compare: split by .
	ap := strings.Split(a, ".")
	bp := strings.Split(b, ".")
	max := len(ap)
	if len(bp) > max {
		max = len(bp)
	}
	for i := 0; i < max; i++ {
		var av, bv int
		if i < len(ap) {
			// strip any non-digit suffix? For simplicity, parse int from start
			numStr := ""
			for _, ch := range ap[i] {
				if ch >= '0' && ch <= '9' {
					numStr += string(ch)
				} else {
					break
				}
			}
			av, _ = strconv.Atoi(numStr)
		}
		if i < len(bp) {
			numStr := ""
			for _, ch := range bp[i] {
				if ch >= '0' && ch <= '9' {
					numStr += string(ch)
				} else {
					break
				}
			}
			bv, _ = strconv.Atoi(numStr)
		}
		if av < bv {
			return -1
		}
		if av > bv {
			return 1
		}
	}
	// If all equal numeric, compare lexicographically
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func printHelp(showPrivate bool) {
	fmt.Printf("direnv v%s\n", versionStr)
	fmt.Printf("Usage: direnv COMMAND [...ARGS]\n\n")
	fmt.Printf("Available commands\n")
	fmt.Printf("------------------\n")
	fmt.Printf("allow [PATH_TO_RC]:\n  aliases: permit, grant\n  Grants direnv permission to load the given .envrc or .env file.\n")
	if showPrivate {
		fmt.Printf("*apply_dump FILE:\n  Accepts a filename containing `direnv dump` output and generates a series of bash export statements to apply the given env\n")
		fmt.Printf("*show_dump DUMP:\n  Show the data inside of a dump for debugging purposes\n")
		fmt.Printf("*check-required SHELL ENVRC_PATH PATH...:\n  Checks if required files have been allowed\n")
	}
	fmt.Printf("block [PATH_TO_RC]:\n  aliases: deny, disallow, revoke\n  Revokes the authorization of a given .envrc or .env file.\n")
	if showPrivate {
		fmt.Printf("*dotenv [SHELL] [PATH_TO_DOTENV]:\n  Transforms a .env file to evaluatable `export KEY=PAIR` statements\n")
		fmt.Printf("*dump [SHELL] [FILE]:\n  Used to export the inner bash state at the end of execution\n")
	}
	fmt.Printf("edit [PATH_TO_RC]:\n  Opens PATH_TO_RC or the current .envrc or .env into an $EDITOR and allow\n  the file to be loaded afterwards.\n")
	fmt.Printf("exec DIR COMMAND [...ARGS]:\n  Executes a command after loading the first .envrc or .env found in DIR\n")
	fmt.Printf("export SHELL:\n  Loads an .envrc or .env and prints the diff in terms of exports.\n  Supported SHELL values are: [bash, zsh, fish, tcsh, elvish, pwsh, murex, json, vim, gha, systemd, gzenv]\n")
	fmt.Printf("fetchurl <url> [<integrity-hash>]:\n  Fetches a given URL into direnv's CAS\n")
	fmt.Printf("help [SHOW_PRIVATE]:\n  Shows this help\n")
	fmt.Printf("hook SHELL:\n  Used to setup the shell hook\n")
	fmt.Printf("prune:\n  Removes old allowed and required files\n")
	fmt.Printf("reload:\n  Triggers an env reload\n")
	fmt.Printf("status [--json]:\n  Prints some debug status information\n")
	fmt.Printf("stdlib:\n  Displays the stdlib available in the .envrc execution context\n")
	fmt.Printf("version [VERSION_AT_LEAST]:\n  prints the version or checks that direnv is older than VERSION_AT_LEAST.\n")
	if showPrivate {
		fmt.Printf("*watch SHELL PATH...:\n  Adds a path to the list that direnv watches for changes\n")
		fmt.Printf("*watch-dir SHELL DIR:\n  Recursively adds a directory to the list that direnv watches for changes\n")
		fmt.Printf("*watch-list [SHELL]:\n  Pipe pairs of `mtime path` to stdin to build a list of files to watch.\n")
		fmt.Printf("*watch-print [--null]:\n  prints the watched paths\n")
		fmt.Printf("*current PATH:\n  Reports whether direnv's view of a file is current (or stale)\n")
	}
	fmt.Printf("log [--status | --error] <message>:\n  Logs a given message\n")
	if showPrivate {
		fmt.Printf("* = private commands\n")
	}
}
