		ConfigDir:      cfgDir,
		SelfPath:       self,
		BashPath:       "/usr/bin/bash",
		WarnTimeout:    "5s",
		WhitelistExact: make(map[string]bool),
		HasConfigFile:  false,
	}
	tomlPath := filepath.Join(cfgDir, "direnv.toml")
	if _, err := os.Stat(tomlPath); os.IsNotExist(err) {
		old := filepath.Join(cfgDir, "config.toml")
		if _, err2 := os.Stat(old); err2 == nil {
			tomlPath = old
		} else {
			return cfg
		}
	}
	data, err := os.ReadFile(tomlPath)
	if err != nil {
		return cfg
	}
	cfg.HasConfigFile = true
	section := ""
	lines := strings.Split(string(data), "\n")
	var accumulatingPrefix bool
	var prefixAcc []string
	var accumulatingExact bool
	var exactAcc []string

	for _, rawLine := range lines {
		line := strings.TrimSpace(rawLine)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			sec := strings.TrimSpace(line[1 : len(line)-1])
			section = sec
			accumulatingPrefix = false
			accumulatingExact = false
			continue
		}
		if section == "whitelist" && accumulatingPrefix {
			if strings.Contains(line, "]") {
				inner := strings.TrimSpace(strings.TrimSuffix(line, "]"))
				inner = strings.TrimSuffix(inner, ",")
				if inner != "" {
					ps, _ := parseTomlString(inner)
					prefixAcc = append(prefixAcc, expandUser(ps))
				}
				accumulatingPrefix = false
				cfg.WhitelistPrefix = prefixAcc
				continue
			}
			inner := strings.TrimSuffix(line, ",")
			if inner != "" {
				ps, _ := parseTomlString(inner)
				prefixAcc = append(prefixAcc, expandUser(ps))
			}
			continue
		}
		if section == "whitelist" && accumulatingExact {
			if strings.Contains(line, "]") {
				inner := strings.TrimSpace(strings.TrimSuffix(line, "]"))
				inner = strings.TrimSuffix(inner, ",")
				if inner != "" {
					ps, _ := parseTomlString(inner)
					exactAcc = append(exactAcc, expandUser(ps))
				}
				accumulatingExact = false
				for _, v := range exactAcc {
					exp := v
					if !strings.HasSuffix(exp, ".envrc") && !strings.HasSuffix(exp, ".env") {
						exp = filepath.Join(exp, ".envrc")
					}
					if !filepath.IsAbs(exp) {
						if ap, err := filepath.Abs(exp); err == nil {
							exp = ap
						}
					}
					cfg.WhitelistExact[exp] = true
				}
				continue
			}
			inner := strings.TrimSuffix(line, ",")
			if inner != "" {
				ps, _ := parseTomlString(inner)
				exactAcc = append(exactAcc, expandUser(ps))
			}
			continue
		}
		eq := strings.Index(line, "=")
		if eq == -1 {
			continue
		}
		key := strings.TrimSpace(line[:eq])
		val := strings.TrimSpace(line[eq+1:])

		if section == "global" {
			switch key {
			case "bash_path":
				if s, err := parseTomlString(val); err == nil {
					cfg.BashPath = s
				}
			case "disable_stdin":
				if b, ok := parseBool(val); ok {
					cfg.DisableStdin = b
				}
			case "warn_timeout":
				if s, err := parseTomlString(val); err == nil {
					cfg.WarnTimeout = s
				}
			case "load_dotenv":
				if b, ok := parseBool(val); ok {
					cfg.LoadDotenv = b
				}
			case "strict_env":
				if b, ok := parseBool(val); ok {
					cfg.StrictEnv = b
				}
			case "hide_env_diff":
				if b, ok := parseBool(val); ok {
					cfg.HideEnvDiff = b
				}
			case "log_format":
				if s, err := parseTomlString(val); err == nil {
					cfg.LogFormat = s
				}
			case "log_filter":
				s, _ := parseTomlString(val)
				if re, err := regexp.Compile(s); err == nil {
					cfg.LogFilter = re
				} else {
					cfg.LogFilterErr = err
				}
			}
		} else if section == "whitelist" {
			if key == "prefix" {
				if strings.HasPrefix(val, "[") && !strings.Contains(val, "]") {
					accumulatingPrefix = true
					prefixAcc = []string{}
					rest := strings.TrimSpace(val[1:])
					if rest != "" && rest != "," {
						rest = strings.TrimSuffix(rest, ",")
						if s, err := parseTomlString(rest); err == nil {
							prefixAcc = append(prefixAcc, expandUser(s))
						}
					}
				} else {
					arr := parseStringArraySimple(val)
					cfg.WhitelistPrefix = arr
				}
			} else if key == "exact" {
				if strings.HasPrefix(val, "[") && !strings.Contains(val, "]") {
					accumulatingExact = true
					exactAcc = []string{}
					rest := strings.TrimSpace(val[1:])
					if rest != "" {
						rest = strings.TrimSuffix(rest, ",")
						if s, err := parseTomlString(rest); err == nil {
							exactAcc = append(exactAcc, expandUser(s))
						}
					}
				} else {
					arr := parseStringArraySimple(val)
					for _, v := range arr {
						exp := v
						if !strings.HasSuffix(exp, ".envrc") && !strings.HasSuffix(exp, ".env") {
							exp = filepath.Join(exp, ".envrc")
						}
						if !filepath.IsAbs(exp) {
							if ap, err := filepath.Abs(exp); err == nil {
								exp = ap
							}
						}
						cfg.WhitelistExact[exp] = true
					}
				}
			}
		}
	}
	return cfg
}

func (c *Config) logStatus(msg string) {
	if c.LogFilterErr != nil {
		fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: error error in log filter: %s\x1b[0m\n", c.LogFilterErr.Error())
	}
	if c.LogFilter != nil {
		if !c.LogFilter.MatchString(msg) {
			return
		}
	}
	if c.LogFormat == "-" {
		return
	}
	if c.LogFormat == "" {
		if !c.HasConfigFile {
			fmt.Fprintf(os.Stderr, "\x1b[0mdirenv: %s\n", msg)
		} else {
			fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
		}
		return
	}
	out := fmt.Sprintf(c.LogFormat, msg)
	if !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	fmt.Fprint(os.Stderr, out)
}

func (c *Config) logError(msg string) {
	if c.HasConfigFile {
		fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
	} else {
		fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: %s\x1b[0m\n", msg)
	}
}

func encodeWatchList(watches []Watch) string {
	b, _ := json.Marshal(watches)
	var buf bytes.Buffer
	zw := zlib.NewWriter(&buf)
	zw.Write(b)
	zw.Close()
	enc := base64.URLEncoding.EncodeToString(buf.Bytes())
	enc = strings.TrimRight(enc, "=")
	return enc
}

func decodeWatchList(s string) ([]Watch, error) {
	if s == "" {
		return []Watch{}, nil
	}
	if m := len(s) % 4; m != 0 {
		s += strings.Repeat("=", 4-m)
	}
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		b, err = base64.StdEncoding.DecodeString(s)
		if err != nil {
			return nil, err
		}
	}
	zr, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	dec, err := io.ReadAll(zr)
	if err != nil {
		return nil, err
	}
	var ws []Watch
	if err := json.Unmarshal(dec, &ws); err != nil {
		return nil, err
	}
	return ws, nil
}

func encodeDiff(d EnvDiff) string {
	b, _ := json.Marshal(d)
	var buf bytes.Buffer
	zw := zlib.NewWriter(&buf)
	zw.Write(b)
	zw.Close()
	enc := base64.URLEncoding.EncodeToString(buf.Bytes())
	enc = strings.TrimRight(enc, "=")
	return enc
}

func decodeDiff(s string) (EnvDiff, error) {
	var d EnvDiff
	if s == "" {
		d.Prev = make(map[string]string)
		d.Next = make(map[string]string)
		return d, nil
	}
	if m := len(s) % 4; m != 0 {
		s += strings.Repeat("=", 4-m)
	}
	b, err := base64.URLEncoding.DecodeString(s)
	if err != nil {
		return d, err
	}
	zr, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return d, err
	}
	defer zr.Close()
	dec, err := io.ReadAll(zr)
	if err != nil {
		return d, err
	}
	if err := json.Unmarshal(dec, &d); err != nil {
		return d, err
	}
	if d.Prev == nil {
		d.Prev = make(map[string]string)
	}
	if d.Next == nil {
		d.Next = make(map[string]string)
	}
	return d, nil
}

func getEnvMap() map[string]string {
	m := make(map[string]string)
	for _, kv := range os.Environ() {
		parts := strings.SplitN(kv, "=", 2)
		if len(parts) == 2 {
			m[parts[0]] = parts[1]
		} else {
			m[parts[0]] = ""
		}
	}
	return m
}

func findRCFromDir(startDir string, loadDotenv bool) (string, bool) {
	dir := startDir
	if !filepath.IsAbs(dir) {
		if ap, err := filepath.Abs(dir); err == nil {
			dir = ap
		}
	}
	for {
		rc1 := filepath.Join(dir, ".envrc")
		if fi, err := os.Stat(rc1); err == nil && !fi.IsDir() {
			return rc1, true
		}
		if loadDotenv {
			rc2 := filepath.Join(dir, ".env")
			if fi, err := os.Stat(rc2); err == nil && !fi.IsDir() {
				return rc2, true
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return "", false
}

func findRCFromPath(p string, loadDotenv bool) (string, error) {
	fi, err := os.Stat(p)
	if err != nil {
		return "", err
	}
	if !fi.IsDir() {
		base := filepath.Base(p)
		if base == ".envrc" || (base == ".env" && loadDotenv) {
			abs, _ := filepath.Abs(p)
			if rp, err := filepath.EvalSymlinks(abs); err == nil {
				abs = rp
			}
			return abs, nil
		}
		dir := filepath.Dir(p)
		if rc, ok := findRCFromDir(dir, loadDotenv); ok {
			return rc, nil
		}
		return "", fmt.Errorf(".envrc file not found")
	}
	if rc, ok := findRCFromDir(p, loadDotenv); ok {
		return rc, nil
	}
	return "", fmt.Errorf(".envrc file not found")
}

func isAllowed(rcPath string, cfg *Config) (int, string, string) {
	absPath, err := filepath.Abs(rcPath)
	if err != nil {
		absPath = rcPath
	}
	if rp, err := filepath.EvalSymlinks(absPath); err == nil {
		absPath = rp
	}
	if cfg.WhitelistExact[absPath] {
		return 0, "", ""
	}
	for _, pref := range cfg.WhitelistPrefix {
		exp := expandUser(pref)
		if !filepath.IsAbs(exp) {
			if ap, err := filepath.Abs(exp); err == nil {
				exp = ap
			}
		}
		if strings.HasPrefix(absPath, exp) {
			return 0, "", ""
		}
	}
	dataDir := getDataDir()
	allowDir := filepath.Join(dataDir, "allow")
	denyDir := filepath.Join(dataDir, "deny")
	hDeny := sha256.Sum256([]byte(absPath + "\n"))
	denyHash := hex.EncodeToString(hDeny[:])
	denyPath := filepath.Join(denyDir, denyHash)
	if _, err := os.Stat(denyPath); err == nil {
		return 2, "", denyPath
	}
	rcContent, err := os.ReadFile(absPath)
	if err != nil {
		return 1, "", denyPath
	}
	hAllow := sha256.Sum256([]byte(absPath + "\n" + string(rcContent)))
	allowHash := hex.EncodeToString(hAllow[:])
	allowPath := filepath.Join(allowDir, allowHash)
	if _, err := os.Stat(allowPath); err == nil {
		return 0, allowPath, denyPath
	}
	return 1, allowPath, denyPath
}

func statModTime(p string) int64 {
	if fi, err := os.Stat(p); err == nil {
		return fi.ModTime().Unix()
	}
	return 0
}

func fileExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func computeWatches(rcPath string, allowPath string, denyPath string, extra []Watch) []Watch {
	var ws []Watch
	ws = append(ws, Watch{Path: rcPath, Modtime: statModTime(rcPath), Exists: true})
	if allowPath != "" {
		ws = append(ws, Watch{Path: allowPath, Modtime: statModTime(allowPath), Exists: fileExists(allowPath)})
	}
	if denyPath != "" {
		ws = append(ws, Watch{Path: denyPath, Modtime: statModTime(denyPath), Exists: fileExists(denyPath)})
	}
	ws = append(ws, extra...)
	return ws
}

func bashEscape(v string) string {
	if v == "" {
		return "''"
	}
	var sb strings.Builder
	sb.WriteString("$'")
	for _, r := range v {
		switch r {
		case '\\':
			sb.WriteString("\\\\")
		case '\'':
			sb.WriteString("\\'")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\a':
			sb.WriteString("\\a")
		case '\b':
			sb.WriteString("\\b")
		case '\v':
			sb.WriteString("\\v")
		case '\f':
			sb.WriteString("\\f")
		case '\x1b':
			sb.WriteString("\\e")
		default:
			if r < 32 || r == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

func computeDiff(clean, newEnv map[string]string) (map[string]string, map[string]string) {
	p := make(map[string]string)
	n := make(map[string]string)
	for k, cv := range clean {
		if nv, ok := newEnv[k]; !ok {
			p[k] = cv
		} else if cv != nv {
			p[k] = cv
			n[k] = nv
		}
	}
	for k, nv := range newEnv {
		if _, ok := clean[k]; !ok {
			n[k] = nv
		}
	}
	return p, n
}

func genGhaDelim() string {
	b := make([]byte, 16)
	rand.Read(b)
	return "ghadelimiter_" + hex.EncodeToString(b)
}

func escapeFish(v string) string {
	return strings.ReplaceAll(strings.ReplaceAll(v, "\\", "\\\\"), "'", "\\'")
}

func escapeTcshVal(v string) string {
	if v == "" {
		return "''"
	}
	var sb strings.Builder
	for _, r := range v {
		switch r {
		case ' ':
			sb.WriteString("\\ ")
		case '\'':
			sb.WriteString("\\'")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteRune('\n')
		case '\r':
			sb.WriteRune('\r')
		case '\t':
			sb.WriteRune('\t')
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func formatSystemd(k, v string) string {
	if v == "" {
		return fmt.Sprintf("%s=", k)
	}
	needsQuote := strings.Contains(v, "\n") || strings.Contains(v, "\"") || strings.Contains(v, "'") || strings.Contains(v, "\\")
	if !needsQuote {
		return fmt.Sprintf("%s=%s", k, v)
	}
	esc := strings.ReplaceAll(v, "\\", "\\\\")
	esc = strings.ReplaceAll(esc, "\"", "\\\"")
	esc = strings.ReplaceAll(esc, "'", "\\'")
	return fmt.Sprintf("%s=\"%s\"", k, esc)
}

func formatExport(shell string, currentEnv, cleanEnv, newNext map[string]string, diffB64 string) string {
	newEnv := make(map[string]string)
	for k, v := range cleanEnv {
		newEnv[k] = v
	}
	for k, v := range newNext {
		newEnv[k] = v
	}
	if diffB64 != "" {
		newEnv["DIRENV_DIFF"] = diffB64
	} else {
		delete(newEnv, "DIRENV_DIFF")
	}

	switch shell {
	case "bash", "zsh":
		var parts []string
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				parts = append(parts, fmt.Sprintf("unset %s;", k))
			}
		}
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			parts = append(parts, fmt.Sprintf("export %s=%s;", k, bashEscape(newEnv[k])))
		}
		return strings.Join(parts, "")
	case "fish":
		var parts []string
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				parts = append(parts, fmt.Sprintf("set -e -g '%s';", strings.ReplaceAll(k, "'", "\\'")))
			}
		}
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			parts = append(parts, fmt.Sprintf("set -x -g '%s' '%s';", strings.ReplaceAll(k, "'", "\\'"), escapeFish(newEnv[k])))
		}
		return strings.Join(parts, "")
	case "tcsh":
		var parts []string
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				parts = append(parts, fmt.Sprintf("unsetenv %s ;", k))
			}
		}
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			parts = append(parts, fmt.Sprintf("setenv %s %s ;", k, escapeTcshVal(newEnv[k])))
		}
		return strings.Join(parts, "")
	case "vim":
		var parts []string
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				parts = append(parts, fmt.Sprintf("call setenv('%s',v:null)\n", strings.ReplaceAll(k, "'", "''")))
			}
		}
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			parts = append(parts, fmt.Sprintf("call setenv('%s','%s')\n", strings.ReplaceAll(k, "'", "''"), strings.ReplaceAll(newEnv[k], "'", "''")))
		}
		return strings.Join(parts, "")
	case "pwsh":
		var parts []string
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				parts = append(parts, fmt.Sprintf("Remove-Item -LiteralPath 'env:/%s';", strings.ReplaceAll(k, "'", "''")))
			}
		}
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			parts = append(parts, fmt.Sprintf("${env:%s}='%s';", strings.ReplaceAll(k, "'", "''"), strings.ReplaceAll(newEnv[k], "'", "''")))
		}
		return strings.Join(parts, "")
	case "json":
		transform := make(map[string]*string)
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				transform[k] = nil
			}
		}
		for k, v := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != v {
				val := v
				transform[k] = &val
			}
		}
		b, _ := json.MarshalIndent(transform, "", "  ")
		return string(b)
	case "elvish", "murex":
		transform := make(map[string]*string)
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				transform[k] = nil
			}
		}
		for k, v := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != v {
				val := v
				transform[k] = &val
			}
		}
		b, _ := json.Marshal(transform)
		return string(b)
	case "gha":
		var parts []string
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		for _, k := range expKeys {
			delim := genGhaDelim()
			parts = append(parts, fmt.Sprintf("%s<<%s\n%s\n%s\n", k, delim, newEnv[k], delim))
		}
		return strings.Join(parts, "")
	case "systemd":
		var expKeys []string
		for k := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != newEnv[k] {
				expKeys = append(expKeys, k)
			}
		}
		sort.Strings(expKeys)
		var parts []string
		for _, k := range expKeys {
			parts = append(parts, formatSystemd(k, newEnv[k]))
		}
		if len(parts) == 0 {
			return ""
		}
		return strings.Join(parts, "\n") + "\n"
	case "gzenv":
		transform := make(map[string]*string)
		for k := range currentEnv {
			if _, ok := newEnv[k]; !ok {
				transform[k] = nil
			}
		}
		for k, v := range newEnv {
			if cv, ok := currentEnv[k]; !ok || cv != v {
				val := v
				transform[k] = &val
			}
		}
		b, _ := json.Marshal(transform)
		var buf bytes.Buffer
		zw := zlib.NewWriter(&buf)
		zw.Write(b)
		zw.Close()
		enc := base64.URLEncoding.EncodeToString(buf.Bytes())
		enc = strings.TrimRight(enc, "=")
		return enc
	default:
		return ""
	}
}

func parseDotenvBytes(data []byte) (map[string]string, error) {
	env := make(map[string]string)
	content := string(data)
	var logicalLines []string
	var cur strings.Builder
	inDouble := false
	inSingle := false
	escape := false
	for i := 0; i < len(content); i++ {
		ch := content[i]
		if escape {
			cur.WriteByte(ch)
			escape = false
			continue
		}
		if ch == '\\' && inDouble {
			cur.WriteByte(ch)
			escape = true
			continue
		}
		if ch == '"' && !inSingle {
			inDouble = !inDouble
			cur.WriteByte(ch)
			continue
		}
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
			cur.WriteByte(ch)
			continue
		}
		if ch == '\n' {
			if inDouble || inSingle {
				cur.WriteByte(ch)
				continue
			}
			logicalLines = append(logicalLines, cur.String())
			cur.Reset()
			continue
		}
		if ch == '\r' {
			if inDouble || inSingle {
				cur.WriteByte('\n')
				if i+1 < len(content) && content[i+1] == '\n' {
					i++
				}
				continue
			}
			logicalLines = append(logicalLines, cur.String())
			cur.Reset()
			if i+1 < len(content) && content[i+1] == '\n' {
				i++
			}
			continue
		}
		cur.WriteByte(ch)
	}
	if cur.Len() > 0 {
		logicalLines = append(logicalLines, cur.String())
	}
	for _, line := range logicalLines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		noExport := trimmed
		if strings.HasPrefix(trimmed, "export ") {
			noExport = strings.TrimSpace(trimmed[len("export "):])
		}
		eqIdx := strings.Index(noExport, "=")
		if eqIdx == -1 {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		key := strings.TrimSpace(noExport[:eqIdx])
		valPart := strings.TrimSpace(noExport[eqIdx+1:])
		if key == "" {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		matched, _ := regexp.MatchString(`^[A-Za-z0-9_\.]+$`, key)
		if !matched {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		if valPart == "" {
			env[key] = ""
			continue
		}
		if strings.HasPrefix(valPart, "'") {
			if len(valPart) >= 2 && valPart[0] == '\'' {
				endIdx := -1
				for j := 1; j < len(valPart); j++ {
					if valPart[j] == '\'' {
						endIdx = j
						break
					}
				}
				if endIdx == -1 {
					return nil, fmt.Errorf("unclosed quoted value in .env file")
				}
				inner := valPart[1:endIdx]
				rest := strings.TrimSpace(valPart[endIdx+1:])
				if rest == "" || strings.HasPrefix(rest, "#") {
					env[key] = inner
					continue
				}
			}
		}
		if strings.HasPrefix(valPart, "\"") {
			if len(valPart) >= 2 && valPart[0] == '"' {
				endIdx := -1
				esc := false
				for j := 1; j < len(valPart); j++ {
					ch := valPart[j]
					if esc {
						esc = false
						continue
					}
					if ch == '\\' {
						esc = true
						continue
					}
					if ch == '"' {
						endIdx = j
						break
					}
				}
				if endIdx == -1 {
					return nil, fmt.Errorf("unclosed quoted value in .env file")
				}
				inner := valPart[1:endIdx]
				rest := strings.TrimSpace(valPart[endIdx+1:])
				if rest == "" || strings.HasPrefix(rest, "#") {
					processed := processDoubleQuoted(inner)
					expanded := expandDotenvVars(processed)
					env[key] = expanded
					continue
				}
			}
		}
		hashIdx := strings.Index(valPart, "#")
		var valNoComment string
		if hashIdx != -1 {
			valNoComment = strings.TrimSpace(valPart[:hashIdx])
		} else {
			valNoComment = strings.TrimSpace(valPart)
		}
		if strings.Contains(valNoComment, " ") || strings.Contains(valNoComment, "\t") {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		expanded := expandDotenvVars(valNoComment)
		env[key] = expanded
	}
	return env, nil
}

func processDoubleQuoted(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if ch == '\\' && i+1 < len(s) {
			next := s[i+1]
			switch next {
			case 'n':
				sb.WriteByte('\n')
				i++
			case 'r':
				sb.WriteByte('\r')
				i++
			case '"':
				sb.WriteByte('"')
				i++
			case '\\':
				sb.WriteByte('\\')
				i++
			case '$':
				sb.WriteByte('$')
				i++
			default:
				sb.WriteByte(next)
				i++
			}
		} else {
			sb.WriteByte(ch)
		}
	}
	return sb.String()
}

func expandDotenvVars(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); {
		if s[i] == '$' {
			if i+1 < len(s) && s[i+1] == '{' {
				end := strings.Index(s[i:], "}")
				if end == -1 {
					sb.WriteByte(s[i])
					i++
					continue
				}
				varName := s[i+2 : i+end]
				val := os.Getenv(varName)
				sb.WriteString(val)
				i += end + 1
				continue
			}
			j := i + 1
			for j < len(s) && (isAlphaNum(s[j]) || s[j] == '_') {
				j++
			}
			if j == i+1 {
				sb.WriteByte(s[i])
				i++
				continue
			}
			varName := s[i+1 : j]
			val := os.Getenv(varName)
			sb.WriteString(val)
			i = j
			continue
		}
		sb.WriteByte(s[i])
		i++
	}
	return sb.String()
}

func isAlphaNum(b byte) bool {
	return (b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') || (b >= '0' && b <= '9')
}

func printHelp(showPrivate bool) {
	fmt.Printf("direnv v%s\n", versionStr)
	fmt.Printf("Usage: direnv COMMAND [...ARGS]\n\n")
	fmt.Printf("Available commands\n")
	fmt.Printf("------------------\n")
	fmt.Printf("allow [PATH_TO_RC]:\n  aliases: permit, grant\n  Grants direnv permission to load the given .envrc or .env file.\n")
	if showPrivate {
		fmt.Printf("*apply_dump FILE:\n  Accepts a filename containing `direnv dump` output and generates a series of bash export statements to apply the given env\n")
		fmt.Printf("*show_dump DUMP:\n  Show the data inside of a dump for debugging purposes\n")
		fmt.Printf("*check-required SHELL ENVRC_PATH PATH...:\n  Checks if required files have been allowed\n")
	}
	fmt.Printf("block [PATH_TO_RC]:\n  aliases: deny, disallow, revoke\n  Revokes the authorization of a given .envrc or .env file.\n")
	if showPrivate {
		fmt.Printf("*dotenv [SHELL] [PATH_TO_DOTENV]:\n  Transforms a .env file to evaluatable `export KEY=PAIR` statements\n")
		fmt.Printf("*dump [SHELL] [FILE]:\n  Used to export the inner bash state at the end of execution\n")
	}
	fmt.Printf("edit [PATH_TO_RC]:\n  Opens PATH_TO_RC or the current .envrc or .env into an $EDITOR and allow\n  the file to be loaded afterwards.\n")
	fmt.Printf("exec DIR COMMAND [...ARGS]:\n  Executes a command after loading the first .envrc or .env found in DIR\n")
	fmt.Printf("export SHELL:\n  Loads an .envrc or .env and prints the diff in terms of exports.\n  Supported SHELL values are: [bash, zsh, fish, tcsh, elvish, pwsh, murex, json, vim, gha, systemd, gzenv]\n")
	fmt.Printf("fetchurl <url> [<integrity-hash>]:\n  Fetches a given URL into direnv's CAS\n")
	fmt.Printf("help [SHOW_PRIVATE]:\n  Shows this help\n")
	fmt.Printf("hook SHELL:\n  Used to setup the shell hook\n")
	fmt.Printf("prune:\n  Removes old allowed and required files\n")
	fmt.Printf("reload:\n  Triggers an env reload\n")
	fmt.Printf("status [--json]:\n  Prints some debug status information\n")
	fmt.Printf("stdlib:\n  Displays the stdlib available in the .envrc execution context\n")
	fmt.Printf("version [VERSION_AT_LEAST]:\n  prints the version or checks that direnv is older than VERSION_AT_LEAST.\n")
	if showPrivate {
		fmt.Printf("*watch SHELL PATH...:\n  Adds a path to the list that direnv watches for changes\n")
		fmt.Printf("*watch-dir SHELL DIR:\n  Recursively adds a directory to the list that direnv watches for changes\n")
		fmt.Printf("*watch-list [SHELL]:\n  Pipe pairs of `mtime path` to stdin to build a list of files to watch.\n")
		fmt.Printf("*watch-print [--null]:\n  prints the watched paths\n")
		fmt.Printf("*current PATH:\n  Reports whether direnv's view of a file is current (or stale)\n")
	}
	fmt.Printf("log [--status | --error] <message>:\n  Logs a given message\n")
	if showPrivate {
		fmt.Printf("* = private commands\n")
	}
}

func main() {
	if len(os.Args) < 2 {
		printHelp(false)
		return
	}
	cfg := loadConfig()
	cmd := os.Args[1]
	args := os.Args[2:]

	switch cmd {
	case "version":
		if len(args) == 0 {
			fmt.Println(versionStr)
			return
		}
		desired := args[0]
		if compareVersions(versionStr, desired) < 0 {
			cfg.logError(fmt.Sprintf("current version v%s is older than the desired version v%s", versionStr, desired))
			os.Exit(1)
		}
		return
	case "help":
		showPrivate := false
		if len(args) > 0 {
			showPrivate = true
		}
		printHelp(showPrivate)
		return
	case "stdlib":
		data, err := os.ReadFile("/tmp/stdlib.sh")
		if err != nil {
			// Try embed location
			if d, err2 := os.ReadFile("/workspace/docs/../man/../tmp/stdlib.sh"); err2 == nil {
				data = d
			} else {
				// fallback: try to call original executable? Use /workspace/executable if exists and is different from self?
				// If self is not the original, we can try to read from original path if available
				if cfg.SelfPath != "/workspace/executable" {
					if out, err3 := exec.Command("/workspace/executable", "stdlib").Output(); err3 == nil {
						data = out
					} else {
						fmt.Fprintln(os.Stderr, "stdlib not found")
						os.Exit(1)
					}
				} else {
					fmt.Fprintln(os.Stderr, "stdlib not found")
					os.Exit(1)
				}
			}
		}
		content := string(data)
		re := regexp.MustCompile(`direnv="[^"]*"`)
		content = re.ReplaceAllString(content, fmt.Sprintf(`direnv="%s"`, cfg.SelfPath))
		fmt.Print(content)
		return
	case "hook":
		if len(args) == 0 {
			cfg.logError("unknown target shell ''")
			os.Exit(1)
		}
		shell := args[0]
		switch shell {
		case "bash":
			fmt.Printf("_direnv_hook() {\n  local previous_exit_status=$?;\n  vars=\"$(\"%s\" export bash)\";\n  trap -- '' SIGINT;\n  eval \"$vars\";\n  trap - SIGINT;\n  return $previous_exit_status;\n};\nif [[ \";${PROMPT_COMMAND[*]:-};\" != *\";_direnv_hook;\"* ]]; then\n  if [[ \"$(declare -p PROMPT_COMMAND 2>&1)\" == \"declare -a\"* ]]; then\n    PROMPT_COMMAND=(_direnv_hook \"${PROMPT_COMMAND[@]}\")\n  else\n    PROMPT_COMMAND=\"_direnv_hook${PROMPT_COMMAND:+;$PROMPT_COMMAND}\"\n  fi\nfi\n", cfg.SelfPath)
		case "zsh":
			fmt.Printf("_direnv_hook() {\n  vars=\"$(\"%s\" export zsh)\"\n  trap -- '' SIGINT\n  eval \"$vars\"\n  trap - SIGINT\n}\ntypeset -ag precmd_functions\nif (( ! ${precmd_functions[(I)_direnv_hook]} )); then\n  precmd_functions=(_direnv_hook $precmd_functions)\nfi\ntypeset -ag chpwd_functions\nif (( ! ${chpwd_functions[(I)_direnv_hook]} )); then\n  chpwd_functions=(_direnv_hook $chpwd_functions)\nfi\n", cfg.SelfPath)
		case "fish":
			fmt.Printf("\n    function __direnv_export_eval --on-event fish_prompt;\n        \"%s\" export fish | source;\n\n        if test \"$direnv_fish_mode\" != \"disable_arrow\";\n            function __direnv_cd_hook --on-variable PWD;\n                if test \"$direnv_fish_mode\" = \"eval_after_arrow\";\n                    set -g __direnv_export_again 0;\n                else\n                    \"%s\" export fish | source;\n                end;\n            end;\n        end;\n    end;\n\n    function __direnv_export_eval_2 --on-event fish_preexec;\n        if set -q __direnv_export_again;\n            set -e __direnv_export_again;\n            \"%s\" export fish | source;\n            echo;\n        end;\n\n        functions --erase __direnv_cd_hook;\n    end;", cfg.SelfPath, cfg.SelfPath, cfg.SelfPath)
		case "tcsh":
			fmt.Printf("alias precmd 'eval `%s export tcsh`'", cfg.SelfPath)
		case "elvish":
			fmt.Printf("## hook for direnv\nset @edit:before-readline = $@edit:before-readline {\n\ttry {\n\t\tvar m = [(\"%s\" export elvish | from-json)]\n\t\tif (> (count $m) 0) {\n\t\t\tset m = (all $m)\n\t\t\tkeys $m | each { |k|\n\t\t\t\tif $m[$k] {\n\t\t\t\t\tset-env $k $m[$k]\n\t\t\t\t} else {\n\t\t\t\t\tunset-env $k\n\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t} catch e {\n\t\techo $e\n\t}\n}\n", cfg.SelfPath)
		case "pwsh":
			fmt.Printf("using namespace System;\nusing namespace System.Management.Automation;\n\nif ($PSVersionTable.PSVersion.Major -lt 7 -or ($PSVersionTable.PSVersion.Major -eq 7 -and $PSVersionTable.PSVersion.Minor -lt 2)) {\n    throw \"direnv: PowerShell version $($PSVersionTable.PSVersion) does not meet the minimum required version 7.2!\"\n}\n\n$hook = [EventHandler[LocationChangedEventArgs]] {\n  param([object] $source, [LocationChangedEventArgs] $eventArgs)\n  end {\n    $export = (%s export pwsh) -join [Environment]::NewLine;\n    if ($export) {\n      Invoke-Expression -Command $export;\n    }\n  }\n};\n$currentAction = $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction;\nif ($currentAction) {\n  $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction = [Delegate]::Combine($currentAction, $hook);\n}\nelse {\n  $ExecutionContext.SessionState.InvokeCommand.LocationChangedAction = $hook;\n};\n", cfg.SelfPath)
		case "murex":
			fmt.Printf("event: onPrompt direnv_hook=before {\n\t\"%s\" export murex -> set exports\n\tif { $exports != \"\" } {\n\t\t$exports -> :json: formap key value {\n\t\t\tif { is-null value } then {\n\t\t\t\t!export \"$key\"\n\t\t\t} else {\n\t\t\t\t$value -> export \"$key\"\n\t\t\t}\n\t\t}\n\t}\n}", cfg.SelfPath)
		case "vim":
			cfg.logError("this feature is not supported. Install the direnv.vim plugin instead")
			os.Exit(1)
		case "gha":
			cfg.logError("Hook not implemented for GitHub Actions shell")
			os.Exit(1)
		case "systemd", "json":
			cfg.logError("this feature is not supported")
			os.Exit(1)
		case "gzenv":
			cfg.logError("the gzenv shell doesn't support hooking")
			os.Exit(1)
		default:
			cfg.logError(fmt.Sprintf("unknown target shell '%s'", shell))
			os.Exit(1)
		}
		return
	case "allow", "permit", "grant":
		var rcPath string
		var err error
		if len(args) == 0 {
			pwd, _ := os.Getwd()
			rcPath, _ = findRCFromDir(pwd, cfg.LoadDotenv)
			if rcPath == "" {
				cfg.logError(".envrc file not found")
				os.Exit(1)
			}
		} else {
			rcPath, err = findRCFromPath(args[0], cfg.LoadDotenv)
			if err != nil {
				cfg.logError(err.Error())
				os.Exit(1)
			}
		}
		content, err := os.ReadFile(rcPath)
		if err != nil {
			cfg.logError(err.Error())
			os.Exit(1)
		}
		absPath, _ := filepath.Abs(rcPath)
		if rp, err := filepath.EvalSymlinks(absPath); err == nil {
			absPath = rp
		}
		h := sha256.Sum256([]byte(absPath + "\n" + string(content)))
		hashStr := hex.EncodeToString(h[:])
		dataDir := getDataDir()
		allowDir := filepath.Join(dataDir, "allow")
		os.MkdirAll(allowDir, 0755)
		allowFile := filepath.Join(allowDir, hashStr)
		os.WriteFile(allowFile, []byte(absPath+"\n"), 0644)
		denyDir := filepath.Join(dataDir, "deny")
		hDeny := sha256.Sum256([]byte(absPath + "\n"))
		denyHash := hex.EncodeToString(hDeny[:])
		denyFile := filepath.Join(denyDir, denyHash)
		os.Remove(denyFile)
		return
	case "deny", "disallow", "block", "revoke":
		var rcPath string
		var err error
		if len(args) == 0 {
			pwd, _ := os.Getwd()
			rcPath, _ = findRCFromDir(pwd, cfg.LoadDotenv)
			if rcPath == "" {
				cfg.logError(".envrc file not found")
				os.Exit(1)
			}
		} else {
			rcPath, err = findRCFromPath(args[0], cfg.LoadDotenv)
			if err != nil {
				cfg.logError(err.Error())
				os.Exit(1)
			}
		}
		absPath, _ := filepath.Abs(rcPath)
		if rp, err := filepath.EvalSymlinks(absPath); err == nil {
			absPath = rp
		}
		content, _ := os.ReadFile(absPath)
		hAllow := sha256.Sum256([]byte(absPath + "\n" + string(content)))
		allowHash := hex.EncodeToString(hAllow[:])
		dataDir := getDataDir()
		allowDir := filepath.Join(dataDir, "allow")
		allowFile := filepath.Join(allowDir, allowHash)
		os.Remove(allowFile)
		denyDir := filepath.Join(dataDir, "deny")
		os.MkdirAll(denyDir, 0755)
		hDeny := sha256.Sum256([]byte(absPath + "\n"))
		denyHash := hex.EncodeToString(hDeny[:])
		denyFile := filepath.Join(denyDir, denyHash)
		os.WriteFile(denyFile, []byte(absPath+"\n"), 0644)
		return
	case "status":
		jsonMode := false
		if len(args) > 0 && args[0] == "--json" {
			jsonMode = true
		}
		currentEnv := getEnvMap()
		pwd, _ := os.Getwd()
		foundRC, _ := findRCFromDir(pwd, cfg.LoadDotenv)
		var foundAllowed int
		var foundAllowPath string
		foundWatches := []Watch{}
		if foundRC != "" {
			allowed, allowPath, _ := isAllowed(foundRC, cfg)
			foundAllowed = allowed
			foundAllowPath = allowPath
			absFound, _ := filepath.Abs(foundRC)
			if rp, err := filepath.EvalSymlinks(absFound); err == nil {
				absFound = rp
			}
			hDeny := sha256.Sum256([]byte(absFound + "\n"))
			denyHash := hex.EncodeToString(hDeny[:])
			dataDir := getDataDir()
			denyPath := filepath.Join(dataDir, "deny", denyHash)
			foundWatches = []Watch{
				{Path: absFound, Modtime: statModTime(absFound), Exists: true},
				{Path: foundAllowPath, Modtime: statModTime(foundAllowPath), Exists: fileExists(foundAllowPath)},
				{Path: denyPath, Modtime: statModTime(denyPath), Exists: fileExists(denyPath)},
			}
		}
		var loadedRC string
		var loadedAllowed int
		var loadedAllowPath string
		var loadedWatches []Watch
		if df, ok := currentEnv["DIRENV_FILE"]; ok && df != "" {
			loadedRC = df
			if watchesB64, ok := currentEnv["DIRENV_WATCHES"]; ok && watchesB64 != "" {
				if ws, err := decodeWatchList(watchesB64); err == nil {
					loadedWatches = ws
				}
			}
			if loadedRC != "" {
				allowed, allowPath, _ := isAllowed(loadedRC, cfg)
				loadedAllowed = allowed
				loadedAllowPath = allowPath
			}
		}
		if jsonMode {
			type rcInfo struct {
				Allowed int    `json:"allowed"`
				Path    string `json:"path"`
			}
			type state struct {
				FoundRC  *rcInfo `json:"foundRC"`
				LoadedRC *rcInfo `json:"loadedRC"`
			}
			type out struct {
				Config struct {
					ConfigDir string `json:"ConfigDir"`
					SelfPath  string `json:"SelfPath"`
				} `json:"config"`
				State state `json:"state"`
			}
			var o out
			o.Config.ConfigDir = cfg.ConfigDir
			o.Config.SelfPath = cfg.SelfPath
			if foundRC != "" {
				o.State.FoundRC = &rcInfo{Allowed: foundAllowed, Path: foundRC}
			}
			if loadedRC != "" {
				o.State.LoadedRC = &rcInfo{Allowed: loadedAllowed, Path: loadedRC}
			}
			b, _ := json.Marshal(o)
			fmt.Println(string(b))
			return
		}
		fmt.Printf("direnv exec path %s\n", cfg.SelfPath)
		fmt.Printf("DIRENV_CONFIG %s\n", cfg.ConfigDir)
		fmt.Printf("bash_path %s\n", cfg.BashPath)
		fmt.Printf("disable_stdin %v\n", cfg.DisableStdin)
		fmt.Printf("warn_timeout %s\n", cfg.WarnTimeout)
		if len(cfg.WhitelistPrefix) == 0 {
			fmt.Printf("whitelist.prefix []\n")
		} else {
			fmt.Printf("whitelist.prefix [%s]\n", strings.Join(cfg.WhitelistPrefix, " "))
		}
		if len(cfg.WhitelistExact) == 0 {
			fmt.Printf("whitelist.exact map[]\n")
		} else {
			var kvs []string
			for k := range cfg.WhitelistExact {
				kvs = append(kvs, fmt.Sprintf("%s:true", k))
			}
			sort.Strings(kvs)
			fmt.Printf("whitelist.exact map[%s]\n", strings.Join(kvs, " "))
		}
		if loadedRC == "" {
			fmt.Printf("No .envrc or .env loaded\n")
		} else {
			fmt.Printf("Loaded RC path %s\n", loadedRC)
			for _, w := range loadedWatches {
				rel, _ := filepath.Rel(pwd, w.Path)
				t := time.Unix(w.Modtime, 0).UTC().Format(time.RFC3339)
				if !w.Exists {
					t = time.Unix(0, 0).UTC().Format(time.RFC3339)
				}
				fmt.Printf("Loaded watch: %q - %s\n", rel, t)
			}
			fmt.Printf("Loaded RC allowed %d\n", loadedAllowed)
			if loadedAllowPath != "" {
				fmt.Printf("Loaded RC allowPath %s\n", loadedAllowPath)
			}
		}
		if foundRC == "" {
			fmt.Printf("No .envrc or .env found\n")
		} else {
			fmt.Printf("Found RC path %s\n", foundRC)
			for _, w := range foundWatches {
