			parts := strings.Fields(line)
			if len(parts) < 2 {
				continue
			}
			mtime, _ := strconv.ParseInt(parts[0], 10, 64)
			path := strings.Join(parts[1:], " ")
			exists := true
			if mtime == 0 {
