		}
		enc := encodeWatchList(watches)
		switch shell {
		case "bash", "zsh":
			fmt.Printf("export DIRENV_WATCHES=$'%s';", enc)
		case "fish":
			fmt.Printf("set -x -g 'DIRENV_WATCHES' '%s';", enc)
