func parseStringArraySimple(val string) []string {
	val = strings.TrimSpace(val)
	if !strings.HasPrefix(val, "[") {
		return nil
	}
	end := strings.LastIndex(val, "]")
	if end == -1 {
		return nil
	}
	inner := strings.TrimSpace(val[1:end])
	if inner == "" {
		return []string{}
	}
	var res []string
	var cur strings.Builder
	inDouble := false
	inSingle := false
	esc := false
	for _, r := range inner {
		if esc {
			cur.WriteRune(r)
			esc = false
			continue
		}
		if r == '\\' {
			esc = true
			continue
		}
		if r == '"' && !inSingle {
			inDouble = !inDouble
			continue
		}
		if r == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if r == ',' && !inDouble && !inSingle {
			s := strings.TrimSpace(cur.String())
			s = expandUser(s)
			if s != "" {
				res = append(res, s)
			}
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if cur.Len() > 0 {
		s := strings.TrimSpace(cur.String())
		s = expandUser(s)
		if s != "" {
			res = append(res, s)
		}
	}
	return res
}
