	if showPrivate {
		fmt.Printf("* = private commands\n")
	}
}
func compareVersions(a, b string) int {
	a = strings.TrimPrefix(a, "v")
	b = strings.TrimPrefix(b, "v")
	if a == b {
		return 0
	}
	ap := strings.Split(a, ".")
	bp := strings.Split(b, ".")
	max := len(ap)
	if len(bp) > max {
		max = len(bp)
	}
	for i := 0; i < max; i++ {
		var av, bv int
		if i < len(ap) {
			numStr := ""
			for _, ch := range ap[i] {
				if ch >= '0' && ch <= '9' {
					numStr += string(ch)
				} else {
					break
				}
			}
			av, _ = strconv.Atoi(numStr)
		}
		if i < len(bp) {
			numStr := ""
			for _, ch := range bp[i] {
				if ch >= '0' && ch <= '9' {
					numStr += string(ch)
				} else {
					break
				}
			}
			bv, _ = strconv.Atoi(numStr)
		}
		if av < bv {
			return -1
		}
		if av > bv {
			return 1
		}
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func main() {
	if len(os.Args) < 2 {
		printHelp(false)
		return
	}
