	sb.WriteString("$'")
	for _, r := range v {
		switch r {
		case '\\':
			sb.WriteString("\\\\")
		case '\'':
			sb.WriteString("\\'")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\a':
			sb.WriteString("\\a")
		case '\b':
			sb.WriteString("\\b")
		case '\v':
			sb.WriteString("\\v")
		case '\f':
			sb.WriteString("\\f")
		case '\x1b':
			sb.WriteString("\\e")
		default:
			if r < 32 || r == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", r))
